// Keep the authored colour/geometry and ownership. Finishing is restricted to
// the shared Robson/Burrard world-space pilot, including moving vehicles.
installVehicleSurface(palette.paint, 'roadster-paint');
installVehicleSurface(palette.dark, 'leather');
installVehicleSurface(palette.rubber, 'rubber');
installVehicleSurface(palette.leather, 'leather');
installVehicleSurface(palette.metal, 'metal');
installVehicleSurface(palette.glass, 'roadster-glass');

/** Metre-space aircraft are already merged by colour. This authored surface
 * role travels with each primitive, allowing metal, rubber and enamel to react
 * differently without splitting the batch or adding another texture. */
function surfaceForColour(colour: number): readonly [number, number] {
  if (colour === C.metal) return [0.27, 0.84];
  if (colour === C.gold) return [0.32, 0.72];
  if (colour === C.rubber) return [0.94, 0];
  if (colour === C.seat) return [0.9, 0];
  if (colour === C.black) return [0.82, 0.02];
  if (colour === C.dark) return [0.63, 0.16];
  return [0.32, 0.08];
}

const finish = surfaceForColour(colour);
const surfaces = new Uint8Array(count * 2);
const packed = finish.map((value) => Math.round(value * 255));
for (let i = 0; i < count; i++) surfaces.set(packed, i * 2);
g.setAttribute(
  'assetSurface',
  new THREE.BufferAttribute(surfaces, 2, true),
);

if (material instanceof THREE.MeshStandardMaterial)
  installVehicleSurface(
    material,
    kind === 'glass' ? 'glazing' : 'aircraft-batch',
  );

const driveChase = this.mode === 'drive'
  ? streetDriveChase(distance, streetShowcaseWeight(this.position.x, this.position.z))
  : null;
const pos = eye.clone().addScaledVector(dir, -(driveChase?.distance ?? distance) * blend);
pos.y += (driveChase?.lift ?? distance * (this.mode === 'walk' ? 0.28 : 0.35)) * blend;

/** A street-scale chase composition. The caller supplies the geographic pilot
 * weight; requested zoom, first-person thresholds and vehicle motion stay intact.
 * Close/cockpit and distant map views retain the existing camera exactly. */
export function streetDriveChase(distance: number, showcaseWeight: number) {
  const weight =
    THREE.MathUtils.clamp(showcaseWeight, 0, 1) *
    THREE.MathUtils.smoothstep(distance, 3.5, 7) *
    (1 - THREE.MathUtils.smoothstep(distance, 32, 72));
  return {
    distance: distance * (1 - weight * 0.26),
    lift: distance * THREE.MathUtils.lerp(0.35, 0.14, weight),
    lookAhead: THREE.MathUtils.lerp(2, 4, weight),
  };
}
